// ISO metric thread (basic profile): flanks at 60°, crest P/8 wide on the major diameter,
// root P/4 wide on the minor one. Each cross-section of a screw is a closed curve whose
// radius follows the thread as the angle turns; lofting sections up the axis and capping
// the ends gives the solid directly, with no Boolean. The nut's thread is the same shape
// grown by the clearance (the "tap"), cut out of the nut body.
fn radius(s, p, rmaj, rmin) {
    let u = s % p;
    if u < 0.0 { u += p; }
    let crest = p / 16.0;
    let root = p / 8.0;
    let flank = p / 2.0 - crest - root;
    if u <= crest || u >= p - crest { return rmaj; }
    if (u - p / 2.0).abs() <= root { return rmin; }
    if u < p / 2.0 { return rmaj - (rmaj - rmin) * (u - crest) / flank; }
    rmin + (rmaj - rmin) * (u - p / 2.0 - root) / flank
}
fn threaded(p, rmaj, rmin, z0, z1) {
    let around = 72;
    let count = ((z1 - z0) / p * 6.0).ceiling().to_int();
    let sections = [];
    for k in 0..=count {
        let z = z0 + (z1 - z0) * k / count;
        let pts = [];
        for i in 0..around {
            let th = 2.0 * PI() * i / around;
            let r = radius(z - p * th / (2.0 * PI()), p, rmaj, rmin);
            pts.push(point(r * cos(th), r * sin(th), z));
        }
        sections.push(polyline(pts, true));
    }
    cap(loft(sections))
}
let rmaj = D / 2.0;
let rmin = D / 2.0 - 0.5413 * P;
screw = threaded(P, rmaj, rmin, 0.0, L);
// the nut sits on the screw at NutZ; its tap runs a pitch past both faces
tap = threaded(P, rmaj + C, rmin + C, NutZ - P, NutZ + H + P);
nut_center = point(0.0, 0.0, NutZ);
nut_corner = S / 2.0 / cos(PI / 6.0);
minor = 2.0 * rmin;
